// aset-keluarga.js — Laporan gabungan lintas-modul: 🏠 Aset Keluarga
// Dipindah ke modules/asset/aset-keluarga.js (Sesi 9 restrukturisasi folder — lihat
// docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// ============================================================================
// FITUR BARU: satu kartu ringkasan di tab Laporan yang menyusun ULANG (bukan
// menduplikasi sumber angka) 3 modul yang selama ini cuma bisa dilihat
// terpisah — (1) Keuangan: saldo akun aktif & total utang/cicilan
// (totalSaldoAkun()/totalDebtValue()/totalCicilanOutstanding(), akun.js/
// cicilan.js/tagihan-kalender.js — TIDAK disentuh), (2) Shop: nilai modal
// stok & piutang pelanggan (totalInventoriBisnisValue()/totalPiutangValue(),
// cobek-etalase.js/piutang-utang.js — TIDAK disentuh), dan (3) Car Notes:
// nilai kendaraan yang SUDAH tercatat di Buku Aset dgn jenis 'Kendaraan'
// (D.assets, aset.js — TIDAK disentuh), dibandingkan dgn jumlah kendaraan
// terdaftar di Car Notes (D.vehicles, vehicle-core.js) supaya user lihat
// kalau ada kendaraan yang belum ikut dihitung ke total aset.
//
// SENGAJA TIDAK mengubah/menduplikasi Kekayaan.renderBersih() (modules-
// calc.js, kartu 🏦 Kekayaan Bersih) — itu tetap SATU-SATUNYA sumber angka
// "kekayaan bersih total" yang dipakai growth-rate/snapshot/FI. Kartu ini
// murni breakdown PER-MODUL dari angka yang sama, supaya bisa dibaca/dicetak
// jadi 1 laporan "Aset Keluarga" lintas Shop/Car Notes/Keuangan — bukan
// sumber kebenaran baru & tidak menambah field data baru sama sekali (pure
// read-only orchestration, pola sama dgn LaporanAset.build()/renderList()
// di aset.js).
//
// build() dipisah dari render() supaya logic murni bisa dites tanpa DOM.
const AsetKeluarga={
// (1) Modul Keuangan: saldo akun aktif dikurangi utang manual + utang buku +
// sisa cicilan/tagihan (definisi SAMA dgn Kekayaan.renderBersih()).
keuangan(){
const saldoAkun=(typeof totalSaldoAkun==='function')?totalSaldoAkun():0;
const utangManual=(D.pajakZakat&&D.pajakZakat.utangJT)||0;
const utangBuku=(typeof totalDebtValue==='function')?totalDebtValue():0;
const cicilan=(typeof totalCicilanOutstanding==='function')?totalCicilanOutstanding():0;
const utang=utangManual+utangBuku+cicilan;
return{saldoAkun,utang,net:saldoAkun-utang};
},
// (2) Modul Shop: nilai modal stok (inventori) + piutang pelanggan yang
// belum lunas (definisi SAMA dgn Kekayaan.renderBersih()).
shop(){
const inventori=(typeof totalInventoriBisnisValue==='function')?totalInventoriBisnisValue():0;
const piutang=(typeof totalPiutangValue==='function')?totalPiutangValue():0;
return{inventori,piutang,net:inventori+piutang};
},
// (3) Modul Car Notes: kendaraan yang dikelola di Car Notes (D.vehicles)
// dibanding aset jenis 'Kendaraan' yang SUDAH dicatat nilainya di Buku Aset
// (D.assets) — TIDAK ADA field penghubung baru, murni baca 2 data yang
// sudah ada apa adanya (nama kendaraan & nama aset bisa beda, jadi
// dibandingkan JUMLAHNYA saja, bukan dicocokkan satu-satu).
// Sesi 197 (Ownership Sync — Family/Aset Keluarga): TAMBAH 1 filter
// isVehicleOwnershipSelf(v.id) di atas D.vehicles (0 logic lama diubah) —
// kendaraan ber-ownership INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY dikecualikan
// dari hitungan "jumlahKendaraan" kartu Aset Keluarga, pola sama persis
// isVehicleOwnershipSelf() di vehicle-core.js (Sesi 196). Guard typeof: kalau
// helper belum dimuat, anggap semua SELF (tidak exclude apa pun).
carNotes(){
const vehicles=(D.vehicles||[]).filter(v=>typeof isVehicleOwnershipSelf!=='function'||isVehicleOwnershipSelf(v.id));
const assetKendaraan=(D.assets||[]).filter(a=>a.jenis==='Kendaraan');
const nilaiTercatat=assetKendaraan.reduce((s,a)=>s+(a.nilai||0),0);
return{jumlahKendaraan:vehicles.length,jumlahAsetKendaraan:assetKendaraan.length,nilaiTercatat};
},
build(){
const keu=AsetKeluarga.keuangan();
const shop=AsetKeluarga.shop();
const cn=AsetKeluarga.carNotes();
const total=keu.net+shop.net+cn.nilaiTercatat;
return{keuangan:keu,shop,carNotes:cn,total};
},
// Render kartu "🏠 Aset Keluarga". Kartu tetap ditampilkan walau semua nol
// (beda dgn LaporanAset yg sembunyi kalau kosong) — supaya user baru yg
// belum isi Shop/Car Notes tetap lihat kartu ini ada & tahu apa isinya.
render(){
const card=document.getElementById('asetKeluargaCard');
if(!card)return;
const d=AsetKeluarga.build();
const keuEl=document.getElementById('akKeuangan');
if(keuEl)keuEl.innerHTML=`<div class="u-flex u-jcb u-fs12 u-mb4"><span>Saldo Akun</span><span class="u-fw700">${fmtFull(d.keuangan.saldoAkun)}</span></div><div class="u-flex u-jcb u-fs12"><span>Utang &amp; Cicilan</span><span class="u-fw700 red">-${fmtFull(d.keuangan.utang)}</span></div>`;
const shopEl=document.getElementById('akShop');
if(shopEl)shopEl.innerHTML=`<div class="u-flex u-jcb u-fs12 u-mb4"><span>Nilai Stok (Inventori)</span><span class="u-fw700">${fmtFull(d.shop.inventori)}</span></div><div class="u-flex u-jcb u-fs12"><span>Piutang Pelanggan</span><span class="u-fw700">${fmtFull(d.shop.piutang)}</span></div>`;
const cnEl=document.getElementById('akCarNotes');
if(cnEl){
const cn=d.carNotes;
let cnHtml=cn.jumlahKendaraan?`<div class="u-flex u-jcb u-fs12"><span>${cn.jumlahKendaraan} kendaraan terdaftar · nilai tercatat</span><span class="u-fw700">${fmtFull(cn.nilaiTercatat)}</span></div>`:'<div class="u-fs12 u-t2">Belum ada kendaraan tercatat di Car Notes.</div>';
if(cn.jumlahKendaraan&&cn.jumlahAsetKendaraan<cn.jumlahKendaraan){
cnHtml+=`<div class="u-fs11 u-t2 u-mt6">ℹ️ Baru ${cn.jumlahAsetKendaraan} dari ${cn.jumlahKendaraan} kendaraan yang punya nilai tercatat di 📋 Buku Aset (jenis "🏍️ Kendaraan") — tambahkan di sana supaya ikut masuk Total Aset Keluarga di bawah.</div>`;
}
cnEl.innerHTML=cnHtml;
}
const totalEl=document.getElementById('akTotal');
if(totalEl){totalEl.textContent=fmtFullSigned(d.total);totalEl.style.color=d.total<0?'var(--accent2)':'';}
}
};

// feature-insights.js — Kartu "💡 Insight ..." di PALING ATAS/dekat 7 fitur (Keuangan, Pajak &
// Dipindah ke modules/ai/feature-insights.js (Sesi 14 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// Zakat, Piutang & Utang, Sewa Kios & Renovasi, Bisnis Shop, Car Notes, Dana Pendidikan), pola
// PERSIS SAMA dgn AssetInsight (lihat aset.js): read-only, tidak nyimpen state sendiri, cuma baca
// ulang D tiap dipanggil. Setiap modul punya compute() yang mengembalikan array item
// {id,level,icon,text,action?} — format SAMA PERSIS dgn item FinCoach (modules-calc.js), supaya
// bisa disinkronkan jadi SATU feed gabungan di widget "🩺 Insight Cepat" Dashboard (lihat
// FinCoach.compute()). render() menampilkan compute() sbg kartu ringkas di masing2 halaman, gaya
// visual sama dgn #assetInsightBody (baris icon+text, u-fs12/u-lh15/u-mb8), TANPA tombol
// dismiss/aksi (itu cuma ada di widget Dashboard).
//
// KeuanganInsight & PiutangUtangInsight KHUSUS: compute()-nya adalah SATU-SATUNYA sumber logic
// utk sinyal² yg dulu ditulis inline di FinCoach (defisit/anggaran/utang jatuh tempo) —
// FinCoach.compute() memanggil compute() modul ini langsung (bukan nulis ulang logicnya) supaya
// kartu di halaman fitur & widget "🩺 Insight Cepat" Dashboard 100% sinkron 1:1, tidak mungkin
// beda isi.
//
// Dipanggil dari render utama masing2 halaman/fitur supaya selalu sinkron tiap save/delete/import:
//   - KeuanganInsight.render()      <- renderKeuangan()    (modules-render.js)
//   - PajakInsight.render()         <- renderPajakZakat()   (modules-render.js)
//   - PiutangUtangInsight.render()  <- Piutang.renderList() & Debt.renderList() (piutang-utang.js)
//   - SewaKiosRenovInsight.render() <- SewaKios.render()    (sewakios.js) & Renov.render() (renovasi.js)
//   - ShopInsight.render()          <- Etalase.renderList()  (cobek-etalase.js)
//   - MobilInsight.render()         <- renderCnTab()         (modules-render.js)
//   - EduFundInsight.render()       <- EduFund.render()      (edukasi-dana.js)
const FeatureInsightUI={
// Render item {icon,text}[] ke dalam card+body dgn id tertentu, sembunyikan card kalau kosong
// TOTAL tidak ada data relevan (beda dgn "tidak ada insight" yg tetap tampil dgn pesan aman).
renderInto(cardId,bodyId,hasData,items,emptyMsg){
const card=document.getElementById(cardId);
const box=document.getElementById(bodyId);
if(!card||!box)return;
if(!hasData){card.classList.add('u-dnone');return;}
card.classList.remove('u-dnone');
// S337 (ROADMAP-v1.1.md #3 / KNOWN-ISSUES.md §4.1, "widget AI" — sisa item
// yang sengaja dikecualikan sesi 281 krn beda pola dari tile ikon
// FEATURE_REGISTRY/LifeOS Areas: emoji di sini dulu inline di tengah baris
// teks). Keputusan desain yang diambil: layout flex icon+text (bukan
// vertical-align inline dlm 1 baris teks) — supaya SVG tetap sejajar rapi
// di baris PERTAMA meski `x.text` panjang & wrap ke beberapa baris (align
// inline murni akan meleset kalau teks wrap). REUSE PENUH
// FeatureIcons.render() (sudah ada, size diperkecil 14px dari default 20px
// biar proporsional dgn u-fs12), fallback ke emoji polos kalau
// FeatureIcons belum dimuat (pola guard typeof sama seperti pemanggil lain
// di app) — tidak pernah pecah/kosong.
box.innerHTML=items.length?items.map(x=>{
const iconHtml=(typeof FeatureIcons!=='undefined')?FeatureIcons.render(x.icon,{size:14}):(x.icon||'');
return `<div class=\"fi-insight-row u-fs12 u-lh15 u-mb8\"><span class=\"fi-insight-icon\">${iconHtml}</span><span>${x.text}</span></div>`;
}).join(''):`<div class=\"u-fs12 u-t2 u-lh15\">${emptyMsg}</div>`;
}
};

const KeuanganInsight={
// ctx (opsional) {now,m,y,txM,inc,exp} — dioper dari FinCoach.compute() (modules-calc.js) supaya
// txM/inc/exp yg sudah dihitung di sana (via renderDashboard()) tidak discan ulang 2x. Dipanggil
// tanpa ctx (dari render() di bawah / KeuanganInsight.compute() langsung) tetap hitung sendiri
// sbg fallback, sama seperti pola ctx di FinCoach — supaya modul ini bisa dipanggil independen.
compute(ctx){
const out=[];
const now=(ctx&&ctx.now)||new Date();
const m=(ctx&&ctx.m!=null)?ctx.m:now.getMonth();
const y=(ctx&&ctx.y!=null)?ctx.y:now.getFullYear();
const txM=(ctx&&ctx.txM)||(D.transactions||[]).filter(t=>{const d=new Date(t.date);return d.getMonth()===m&&d.getFullYear()===y;});
const inc=(ctx&&ctx.inc!=null)?ctx.inc:txM.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0);
const exp=(ctx&&ctx.exp!=null)?ctx.exp:txM.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);
// (1) Defisit bulan berjalan (pengeluaran > pemasukan bulan ini)
if(inc>0&&exp>inc){
out.push({id:'defisit',level:'danger',icon:'🔴',text:`Bulan ini pengeluaran (${fmtFull(exp)}) sudah melebihi pemasukan (${fmtFull(inc)}) — defisit ${fmtFull(exp-inc)}.`,action:{label:'Cek Laporan',page:'keuangan',navIdx:1}});
}
// (2) Anggaran paling parah (>=80% terpakai), ambil yang paling tinggi persennya
try{
if((D.budgets||[]).length){
const rows=D.budgets.map(b=>{
const used=(D.transactions||[]).filter(t=>{const d=new Date(t.date);return d.getMonth()===m&&d.getFullYear()===y&&budgetMatchesTx(b,t);}).reduce((s,t)=>s+t.amount,0);
const pct=b.limit>0?Math.round(used/b.limit*100):0;
return{b,pct};
}).filter(r=>r.pct>=80).sort((a,b)=>b.pct-a.pct);
if(rows.length){
const r=rows[0],over=r.pct>=100;
out.push({id:'budget-'+r.b.id,level:over?'danger':'warning',icon:over?'🔴':'🟠',text:`Anggaran "${escapeHtml(r.b.name)}" sudah ${r.pct}% terpakai${over?' (OVER)':''}${rows.length>1?` (+${rows.length-1} anggaran lain juga ketat)`:''}.`,action:{label:'Lihat Anggaran',page:'keuangan',navIdx:1}});
}
}
}catch(e){console.warn('KeuanganInsight: gagal cek anggaran',e);}
return out;
},
// render(ctx) — ctx opsional {now,m,y,txM,inc,exp}, dioper dari renderKeuangan()
// (modules-render.js) KALAU bulan yg lagi dibuka user == bulan berjalan asli,
// supaya txM/inc/exp yg sudah dihitung di sana tidak discan ulang. Tanpa ctx
// (page lain sedang lihat bulan lampau/depan) tetap fallback hitung sendiri
// via compute() apa adanya — PERSIS perilaku lama, 0 perubahan hasil.
render(ctx){
const hasData=!!((D.transactions&&D.transactions.length)||(D.budgets&&D.budgets.length));
FeatureInsightUI.renderInto('keuanganInsightCard','keuanganInsightBody',hasData,KeuanganInsight.compute(ctx),'Belum ada insight khusus — kondisi keuangan kamu bulan ini terlihat aman.');
}
};

const PajakInsight={
compute(){
const out=[];
const pz=D.pajakZakat;
if(!pz)return out;
const now=new Date();
// (1) Zakat Penghasilan bulan ini sudah wajib (>= nisab) tapi belum dicatat dibayar bulan ini.
try{
const incomeBulan=(D.transactions||[]).filter(t=>t.type==='income'&&(()=>{const d=new Date(t.date);return d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear();})()).reduce((s,t)=>s+(t.amount||0),0);
const nisabBulan=pz.nisabPenghasilanBulan||0;
if(incomeBulan>0&&nisabBulan>0&&incomeBulan>=nisabBulan){
const sudahBayar=(pz.zakatLog||[]).some(l=>l.jenis==='penghasilan'&&(()=>{const d=new Date(l.tanggal);return d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear();})());
if(!sudahBayar){
const zakat=Math.round(incomeBulan*0.025);
out.push({id:'pajak-zakat-penghasilan',level:'info',icon:'🕌',text:`Pemasukan bulan ini (${fmtFull(incomeBulan)}) sudah di atas nisab — estimasi Zakat Penghasilan <b>${fmtFull(zakat)}</b>, belum dicatat dibayar bulan ini.`,action:{label:'Lihat Zakat',page:'pajak',navIdx:5}});
}
}
}catch(e){console.warn('PajakInsight: gagal cek zakat penghasilan',e);}
// (2) PBB terikat ke Tagihan & jatuh tempo dekat (<=30 hari)/lewat.
try{
const bill=(D.bills||[]).find(b=>b.pbbLink);
if(bill&&typeof daysUntilDate==='function'){
const d=daysUntilDate(bill.nextDue);
if(d!==null&&d<=30){
const late=d<0;
const kapan=late?`sudah lewat ${Math.abs(d)} hari dari jatuh tempo`:(d===0?'jatuh tempo hari ini':`jatuh tempo ${d} hari lagi`);
out.push({id:'pajak-pbb-due',level:late?'danger':'warning',icon:late?'🔴':'🟠',text:`PBB ${kapan} — estimasi ${fmtFull(bill.amount)}.`,action:{label:'Lihat PBB',page:'pajak',navIdx:5}});
}
}
}catch(e){console.warn('PajakInsight: gagal cek PBB',e);}
// (3) Zakat Maal sudah mencapai haul (≥354 hari) — siap dihitung & dicatat.
try{
if(pz.haulMaalMulai){
const mulai=new Date(pz.haulMaalMulai);
const hariBerjalan=Math.floor((now-mulai)/86400000);
if(hariBerjalan>=354){
out.push({id:'pajak-zakat-maal-haul',level:'info',icon:'🕌',text:`Zakat Maal sudah mencapai haul (≥354 hari sejak ${fmtDateID(pz.haulMaalMulai)}) — cek halaman Zakat Maal untuk hitung & catat kewajiban.`,action:{label:'Lihat Zakat Maal',page:'pajak',navIdx:5}});
}
}
}catch(e){console.warn('PajakInsight: gagal cek haul zakat maal',e);}
return out;
},
render(){
const hasData=!!(D.pajakZakat);
FeatureInsightUI.renderInto('pajakInsightCard','pajakInsightBody',hasData,PajakInsight.compute(),'Belum ada insight khusus — data pajak/zakat kamu sejauh ini terlihat wajar.');
}
};

const PiutangUtangInsight={
// DSR (Debt Service Ratio) dianggap berat kalau total cicilan/bulan sudah >=35% dari rata-rata
// pemasukan bulanan — ambang umum yg juga dipakai sbg rule of thumb perencanaan keuangan.
DSR_WARN_PCT:35,
compute(){
const out=[];
const now=new Date();
if(typeof daysUntilDate!=='function')return out;
// (1) Piutang jatuh tempo dekat (<=7 hari)/lewat, belum lunas — prioritas nagih.
// (Sesi 265, Ownership Sync — AI): TAMBAH filter isPiutangOwnershipSelf (0
// logic lama diubah), pola sama persis prodSelfFilter/cobSelfFilter di
// bawah — piutang ber-ownership INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY
// dikecualikan dari insight nagih. Guard typeof: fallback semua SELF.
try{
const piutangSelfFilter=typeof isPiutangOwnershipSelf==='function'?isPiutangOwnershipSelf:(()=>true);
(D.piutang||[]).filter(p=>!p.lunas&&p.jatuhTempo).filter(piutangSelfFilter).forEach(p=>{
const d=daysUntilDate(p.jatuhTempo);
if(d===null||d>7)return;
const late=d<0;
const kapan=late?`sudah lewat ${Math.abs(d)} hari dari`:(d===0?'jatuh tempo hari ini untuk':`jatuh tempo ${d} hari lagi untuk`);
out.push({id:'piutang-due-'+p.id,level:late?'danger':'warning',icon:late?'🔴':'🟠',text:`Piutang "${escapeHtml(p.name)}" (${fmtFull(p.nilai)}) ${kapan} ditagih.`,action:{label:'Lihat Piutang',page:'pajak',navIdx:5}});
});
}catch(e){console.warn('PiutangUtangInsight: gagal cek piutang',e);}
// (2) Utang jatuh tempo dekat (<=7 hari)/lewat, belum lunas — sama seperti FinCoach lama #6.
// KW-170: ikut cek cicilan barang aktif (Debt.billCicilanAktif(), sudah dianggap "utang beneran"
// di Buku Utang), digabung & diambil yang paling dekat jatuh temponya dari kedua sumber.
// (Sesi 265, Ownership Sync — AI): TAMBAH filter isDebtOwnershipSelf (0
// logic lama diubah) — utang non-SELF dikecualikan dari insight jatuh
// tempo. Guard typeof: fallback semua SELF.
try{
const debtSelfFilter=typeof isDebtOwnershipSelf==='function'?isDebtOwnershipSelf:(()=>true);
const soonDebt=(D.debts||[]).filter(d=>!d.lunas&&d.jatuhTempo).filter(debtSelfFilter).map(d=>({id:'debt-due-'+d.id,name:d.name,nilai:d.nilai,diff:daysUntilDate(d.jatuhTempo)}));
const billCicilan=(typeof Debt!=='undefined'&&typeof Debt.billCicilanAktif==='function')?Debt.billCicilanAktif():[];
const soonBill=billCicilan.filter(b=>b.nextDue).map(b=>({id:'debt-due-bill-'+b.id,name:b.name,nilai:b.amount,diff:daysUntilDate(b.nextDue)}));
const soon=soonDebt.concat(soonBill).filter(x=>x.diff!==null&&x.diff<=7).sort((a,b)=>a.diff-b.diff);
if(soon.length){
const x=soon[0],late=x.diff<0;
out.push({id:x.id,level:late?'danger':'warning',icon:late?'🔴':'🟠',text:`Utang "${escapeHtml(x.name)}" (${fmtFull(x.nilai)}) ${late?'sudah lewat '+Math.abs(x.diff)+' hari dari':x.diff===0?'jatuh tempo hari ini':x.diff+' hari lagi ke'} tanggal jatuh tempo.`,action:{label:'Lihat Utang',page:'pajak',navIdx:5}});
}
}catch(e){console.warn('PiutangUtangInsight: gagal cek utang',e);}
// (3) DSR (beban cicilan/bulan dibanding rata-rata pemasukan) sudah berat (>=35%).
try{
if(typeof DebtStrategy!=='undefined'&&typeof WorthIt!=='undefined'){
const dsr=DebtStrategy.computeDSR();
if(dsr.pct!=null&&dsr.pct>=PiutangUtangInsight.DSR_WARN_PCT){
out.push({id:'debt-dsr-tinggi',level:dsr.pct>=50?'danger':'warning',icon:dsr.pct>=50?'🔴':'🟠',text:`Beban cicilan bulanan (DSR) sudah ${Math.round(dsr.pct)}% dari rata-rata pemasukan (${fmtFull(dsr.totalCicilan)}/bln) — idealnya di bawah ${PiutangUtangInsight.DSR_WARN_PCT}%.`,action:{label:'Lihat Strategi Utang',page:'keuangan',navIdx:1}});
}
}
}catch(e){console.warn('PiutangUtangInsight: gagal cek DSR',e);}
return out;
},
render(){
const billCicilanCount=(typeof Debt!=='undefined'&&typeof Debt.billCicilanAktif==='function')?Debt.billCicilanAktif().length:0;
const hasData=!!((D.piutang&&D.piutang.length)||(D.debts&&D.debts.length)||billCicilanCount);
FeatureInsightUI.renderInto('piutangUtangInsightCard','piutangUtangInsightBody',hasData,PiutangUtangInsight.compute(),'Belum ada insight khusus — piutang & utang kamu sejauh ini aman.');
}
};

const ShopInsight={
// Ambang batas margin bulan ini dianggap turun signifikan dari bulan lalu (sama dgn FinCoach #8).
MARGIN_DROP_RATIO:0.75,
compute(){
const out=[];
// S260 (Business AI Ownership Sync): Shop AI Insight HANYA menghitung produk
// ownership SELF — reuse isProductOwnershipSelf() (SSOT, cobek-etalase.js),
// guard typeof biar aman kalau file itu belum dimuat (fallback anggap semua
// SELF), pola SAMA PERSIS cobSelfFilter/cobSelfFilter2 di bawah (S194, versi
// transaksi) & selfFilter di InventoryEngine/StockRekoWidget/PriceRekoWidget
// (S259/S260).
const prodSelfFilter=typeof isProductOwnershipSelf==='function'?isProductOwnershipSelf:(()=>true);
const products=(D.products||[]).filter(prodSelfFilter);
// (1) Stok menipis (<=2, sama dgn ambang badge "Menipis" di Etalase.renderList()).
const menipis=products.filter(p=>(p.stock||0)<=2);
if(menipis.length){
const contoh=menipis.slice(0,2).map(p=>escapeHtml(p.name)).join(', ');
out.push({id:'shop-stok-menipis',level:'warning',icon:'🟠',text:`${menipis.length} produk stoknya menipis (≤2)${menipis.length?': <b>'+contoh+'</b>'+(menipis.length>2?` +${menipis.length-2} lainnya`:''):''} — pertimbangkan restock.`,action:{label:'Lihat Shop',page:'shop',navIdx:2}});
}
// (2) Margin profit bulan ini turun jauh dari bulan lalu (min. 3 transaksi biar tidak false-positive).
try{
// Sesi 194 (Ownership Sync Shop): AI Insight margin Shop HANYA hitung
// transaksi ownership SELF (guard typeof biar aman kalau ownership-engine.js
// belum dimuat — fallback isCobekOwnershipSelf true).
const cobSelfFilter=typeof isCobekOwnershipSelf==='function'?isCobekOwnershipSelf:(()=>true);
const now=new Date(),m=now.getMonth(),y=now.getFullYear();
const cobek=D.cobek||[];
const cobThis=cobek.filter(t=>{const d=new Date(t.date);return d.getMonth()===m&&d.getFullYear()===y;}).filter(cobSelfFilter);
const prevD=new Date(y,m-1,1);
const cobPrev=cobek.filter(t=>{const d=new Date(t.date);return d.getMonth()===prevD.getMonth()&&d.getFullYear()===prevD.getFullYear();}).filter(cobSelfFilter);
const marginOf=rows=>{const omzet=rows.reduce((s,t)=>s+(t.total||0),0);const profit=rows.reduce((s,t)=>s+(t.profit||0),0);return omzet>0?profit/omzet:null;};
const mThis=marginOf(cobThis),mPrev=marginOf(cobPrev);
if(mThis!=null&&mPrev!=null&&mPrev>0&&mThis<mPrev*ShopInsight.MARGIN_DROP_RATIO&&cobThis.length>=3){
out.push({id:'shop-margin',level:'warning',icon:'🟠',text:`Margin profit Shop bulan ini turun ke ${Math.round(mThis*100)}% (bulan lalu ${Math.round(mPrev*100)}%) — cek lagi harga modal/jual produk terbaru.`,action:{label:'Lihat Shop',page:'shop',navIdx:2}});
}
}catch(e){console.warn('ShopInsight: gagal cek margin',e);}
// (3) Produk terlaris bulan ini (penguat positif, bukan cuma peringatan).
try{
const now=new Date(),m=now.getMonth(),y=now.getFullYear();
// Sesi 194 (Ownership Sync Shop): "Produk terlaris" HANYA hitung transaksi ownership SELF.
const cobSelfFilter2=typeof isCobekOwnershipSelf==='function'?isCobekOwnershipSelf:(()=>true);
const cobThis=(D.cobek||[]).filter(t=>{const d=new Date(t.date);return d.getMonth()===m&&d.getFullYear()===y;}).filter(cobSelfFilter2);
if(cobThis.length>=3){
const perProduk={};
cobThis.forEach(t=>{(t.items||[]).forEach(it=>{const key=it.productId||it.name;if(!key)return;perProduk[key]=(perProduk[key]||{name:it.name,qty:0});perProduk[key].qty+=(it.qty||1);});});
const sorted=Object.values(perProduk).sort((a,b)=>b.qty-a.qty);
if(sorted.length){
out.push({id:'shop-terlaris',level:'good',icon:'🟢',text:`Produk terlaris bulan ini: <b>${escapeHtml(sorted[0].name)}</b> (${sorted[0].qty}x terjual).`});
}
}
}catch(e){console.warn('ShopInsight: gagal cek produk terlaris',e);}
// (4) Estimasi modal restock (S199, Finalisasi Integrasi Shop) — 100%
// reuse ShopBusinessEnginePresenter.summary().purchase (S198
// InventoryEngine.restockScan()+PurchaseEngine.estimatedCost()), 0 rumus
// baru di sini. Beda dari insight (1) di atas: (1) cuma menghitung JUMLAH
// produk stok menipis (ambang stock<=2), item ini menambahkan ESTIMASI
// MODAL (Rp) yang dibutuhkan utk restock semua produk yang direkomendasikan
// StockRekoWidget.scan() (bisa beda produk/ambang dari (1), krn StockRekoWidget
// juga mempertimbangkan histori penjualan/estimasi hari stok tersisa).
try{
if(typeof ShopBusinessEnginePresenter!=='undefined'){
const s=ShopBusinessEnginePresenter.summary();
if(s.purchase&&s.purchase.ok&&s.purchase.itemCount>0){
const money=typeof fmt==='function'?fmt:(n=>'Rp '+Math.round(n||0));
out.push({id:'shop-restock-modal',level:'warning',icon:'🟠',text:`${s.purchase.itemCount} produk direkomendasikan direstock — estimasi modal ${money(s.purchase.totalCost)}.`,action:{label:'Lihat Shop',page:'shop',navIdx:2}});
}
}
}catch(e){console.warn('ShopInsight: gagal cek estimasi modal restock',e);}
// (5) Rencana Pengiriman (S203, Delivery Plan UI) — 100% reuse
// TripEngine.weight()/volume() (S198, delegasi PERSIS ke
// weightCalculator()/volumeCalculator() cobek-etalase.js), TIDAK ada rumus
// baru di sini. Murni deteksi: ada produk dgn data berat/dimensi terisi
// (S203, field baru productModal) -> arahkan ke fitur baru itu.
try{
if(typeof TripEngine!=='undefined'){
const withDims=products.filter(p=>(p.beratPerUnit>0)||(p.panjang>0&&p.lebar>0&&p.tinggi>0));
if(withDims.length>0){
out.push({id:'shop-delivery-plan',level:'info',icon:'🚚',text:`${withDims.length} produk sudah punya data berat/dimensi — pakai 🚚 Rencana Pengiriman di form Transaksi Baru buat cek ongkir & kapasitas kendaraan sebelum kirim pesanan besar.`,action:{label:'Lihat Shop',page:'shop',navIdx:2}});
}
}
}catch(e){console.warn('ShopInsight: gagal cek rencana pengiriman',e);}
// (6) Margin Tipis Pengiriman (S204-A, Trip Presenter) — 100% reuse
// TripPresenter.summary() (agregasi field D.cobek yang sudah tersimpan:
// delivered/ongkir/marginPct + getAIDeliveryThinMarginThreshold() S9),
// TIDAK ada rumus baru di sini. Beda dari rule AI 'delivery-thin-margin'
// (AIDecision, per-transaksi saat save()): item ini ringkasan BULANAN di
// AI Insight Shop.
try{
if(typeof TripPresenter!=='undefined'){
const s=TripPresenter.summary();
if(s.ok&&s.thinMarginCount>0){
out.push({id:'shop-trip-thin-margin',level:'warning',icon:'🟠',text:`${s.thinMarginCount} dari ${s.trips} pengiriman bulan ini bermargin tipis (di bawah ${s.thinThreshold}%).`,action:{label:'Lihat Shop',page:'shop',navIdx:2}});
}
}
}catch(e){console.warn('ShopInsight: gagal cek margin tipis pengiriman',e);}
// (7) Business KPI Recommendation (S211-212, Business Flow KPI) — 100%
// reuse BusinessFlowPresenter.recommendation() (murni derived dari
// businessKPI()/flow()/purchaseStatus() yang sudah ada, S205-S211), TIDAK
// ada rumus baru di sini — cuma nyalurkan hasilnya ke feed AI Insight
// Shop supaya satu sumber angka sama dgn kartu Dashboard KPI.
try{
if(typeof BusinessFlowPresenter!=='undefined'){
BusinessFlowPresenter.recommendation().forEach(item=>out.push(item));
}
}catch(e){console.warn('ShopInsight: gagal cek business KPI recommendation',e);}
return out;
},
render(){
const hasData=!!((D.products&&D.products.length)||(D.cobek&&D.cobek.length));
FeatureInsightUI.renderInto('shopInsightCard','shopInsightBody',hasData,ShopInsight.compute(),'Belum ada insight khusus — data Shop kamu sejauh ini terlihat wajar.');
}
};

const MobilInsight={
compute(){
const out=[];
// Sesi 197 (Ownership Sync — Insight): TAMBAH 1 filter
// isVehicleOwnershipSelf(v.id) di atas D.vehicles (0 logic lama diubah) —
// kendaraan ber-ownership INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY dikecualikan
// dari insight pajak kendaraan, pola sama persis isVehicleOwnershipSelf()
// di vehicle-core.js (Sesi 196). SIM (D.simList) TIDAK difilter — bukan
// entitas kendaraan, tidak punya konsep ownership.
const vehicles=(D.vehicles||[]).filter(v=>typeof isVehicleOwnershipSelf!=='function'||isVehicleOwnershipSelf(v.id));
if(typeof daysUntilDate!=='function')return out;
// (1) Pajak Kendaraan (STNK Tahunan/Ganti Plat 5th/Uji Kelayakan) jatuh tempo dekat/lewat.
vehicles.forEach(v=>{
Object.entries(VEHTAX_ITEMS||{}).forEach(([key,cfg])=>{
const d=daysUntilDate(v[cfg.tglKey]);
if(d===null)return;
if(d<=30){
const late=d<0;
const kapan=late?`sudah lewat ${Math.abs(d)} hari dari`:(d===0?'jatuh tempo hari ini untuk':`jatuh tempo ${d} hari lagi untuk`);
out.push({id:'mobil-tax-'+v.id+'-'+key,level:late?'danger':'warning',icon:late?'🔴':'🟠',text:`${cfg.label} ${escapeHtml(v.name)} ${kapan.includes('hari ini')?kapan:kapan+' tanggal jatuh tempo'}.`,action:{label:'Lihat Pajak Kendaraan',page:'carnotes',navIdx:4}});
}
});
});
// (2) SIM jatuh tempo dekat/lewat.
(D.simList||[]).forEach(s=>{
const d=daysUntilDate(s.tglAkhir);
if(d===null)return;
if(d<=30){
const late=d<0;
const kapan=late?`sudah lewat ${Math.abs(d)} hari dari masa berlaku`:(d===0?'jatuh tempo hari ini':`jatuh tempo ${d} hari lagi`);
out.push({id:'mobil-sim-'+s.id,level:late?'danger':'warning',icon:'🪪',text:`SIM ${escapeHtml(s.nama)} (${s.jenis}) ${kapan}.`,action:{label:'Lihat SIM',page:'carnotes',navIdx:4}});
}
});
return out;
},
render(){
const hasData=!!((D.vehicles&&D.vehicles.length));
FeatureInsightUI.renderInto('mobilInsightCard','mobilInsightBody',hasData,MobilInsight.compute(),'Belum ada insight khusus — pajak kendaraan & SIM kamu sejauh ini aman.');
}
};

const SewaKiosRenovInsight={
// Unit dianggap "kosong berkepanjangan" kalau sudah >=30 hari sejak terakhir masuk status 'kosong'.
KOSONG_LAMA_HARI:30,
// Proyek renovasi dianggap "mandek" kalau sudah >=60 hari sejak dibuat tapi masih ada sisa belum lunas.
RENOV_MANDEK_HARI:60,
compute(){
const out=[];
const now=new Date();
// (1) Unit kios kosong berkepanjangan (belum ada penyewa, sudah lama nganggur).
try{
(D.sewaKios&&D.sewaKios.units||[]).filter(u=>u.status==='kosong').forEach(u=>{
const log=(u.statusLog||[]).filter(l=>l.status==='kosong');
const sejak=log.length?log[log.length-1].tanggal:u.mulai;
if(!sejak)return;
const hari=Math.floor((now-new Date(sejak))/86400000);
if(hari>=SewaKiosRenovInsight.KOSONG_LAMA_HARI){
out.push({id:'sewakios-kosong-'+u.id,level:'warning',icon:'🟠',text:`Unit "${escapeHtml(u.name)}" sudah kosong ${hari} hari — pertimbangkan turunkan harga sewa atau promosikan lagi.`,action:{label:'Lihat Sewa Kios',page:'keuangan',navIdx:1}});
}
});
}catch(e){console.warn('SewaKiosRenovInsight: gagal cek unit kosong',e);}
// (2) Sewa yang akan jatuh tempo tagih dalam <=5 hari (sinkron dgn logic SewaKios.nextTagih()).
try{
if(typeof SewaKios!=='undefined'){
(D.sewaKios&&D.sewaKios.units||[]).forEach(u=>{
const nt=SewaKios.nextTagih(u);
if(!nt||nt.diffDays>5)return;
const late=nt.diffDays<0;
const kapan=late?`sudah lewat ${Math.abs(nt.diffDays)} hari dari`:(nt.diffDays===0?'jatuh tempo hari ini untuk':`jatuh tempo ${nt.diffDays} hari lagi untuk`);
out.push({id:'sewakios-tagih-'+u.id,level:late?'danger':'warning',icon:late?'🔴':'🔔',text:`Sewa unit "${escapeHtml(u.name)}"${u.penyewa?' ('+escapeHtml(u.penyewa)+')':''} ${kapan} penagihan bulan ini.`,action:{label:'Lihat Sewa Kios',page:'keuangan',navIdx:1}});
});
}
}catch(e){console.warn('SewaKiosRenovInsight: gagal cek tagihan sewa',e);}
// (3) Proyek renovasi mandek: sudah lama dibuat, masih ada sisa item belum lunas.
try{
if(typeof Renov!=='undefined'){
(D.renovProjects||[]).forEach(p=>{
const t=Renov.totals(p);
if(t.sisa<=0||!p.createdAt)return;
const hari=Math.floor((now-new Date(p.createdAt))/86400000);
if(hari>=SewaKiosRenovInsight.RENOV_MANDEK_HARI){
out.push({id:'renov-mandek-'+p.id,level:'info',icon:'🛠️',text:`Proyek renovasi "${escapeHtml(p.name)}" sudah ${hari} hari berjalan, masih sisa ${fmtFull(t.sisa)} (${t.paidCount}/${t.count} item lunas).`,action:{label:'Lihat Renovasi',page:'keuangan',navIdx:1}});
}
});
}
}catch(e){console.warn('SewaKiosRenovInsight: gagal cek proyek renovasi',e);}
return out;
},
render(){
const hasData=!!((D.sewaKios&&D.sewaKios.units&&D.sewaKios.units.length)||(D.renovProjects&&D.renovProjects.length));
FeatureInsightUI.renderInto('sewaKiosRenovInsightCard','sewaKiosRenovInsightBody',hasData,SewaKiosRenovInsight.compute(),'Belum ada insight khusus — Sewa Kios & Renovasi kamu sejauh ini aman.');
}
};

const EduFundInsight={
// Target dianggap "mepet" kalau tahun target tinggal <=2 tahun lagi tapi masih ada kekurangan dana.
MEPET_TAHUN:2,
compute(){
const out=[];
if(typeof EduFund==='undefined')return out;
(D.eduFunds||[]).forEach(f=>{
try{
const c=EduFund.calc(f);
if(c.kekurangan<=0)return; // sudah cukup/lebih, tidak perlu insight
if(c.n<=0){
out.push({id:'edufund-lewat-'+f.id,level:'danger',icon:'🔴',text:`Target dana pendidikan "${escapeHtml(f.name)}" tahun ${f.tahunTarget} sudah lewat/tahun ini — masih kurang ${fmtFull(c.kekurangan)}.`,action:{label:'Lihat Dana Pendidikan',page:'settings',navIdx:6}});
}else if(c.n<=EduFundInsight.MEPET_TAHUN){
out.push({id:'edufund-mepet-'+f.id,level:'warning',icon:'🟠',text:`Target dana pendidikan "${escapeHtml(f.name)}" tinggal ${c.n} tahun lagi, masih kurang ${fmtFull(c.kekurangan)} — perlu nabung ≈${fmtFull(c.pmtBulanan)}/bulan.`,action:{label:'Lihat Dana Pendidikan',page:'settings',navIdx:6}});
}
}catch(e){console.warn('EduFundInsight: gagal hitung',f&&f.name,e);}
});
return out;
},
render(){
const hasData=!!(D.eduFunds&&D.eduFunds.length);
FeatureInsightUI.renderInto('eduFundInsightCard','eduFundInsightBody',hasData,EduFundInsight.compute(),'Belum ada insight khusus — target dana pendidikan kamu sejauh ini masih di jalur aman.');
}
};

// invest-ai-widget.js — Widget "🤖 Rekomendasi AI" otomatis di kartu 🧭
// Dipindah ke modules/asset/invest-ai-widget.js (Sesi 9 restrukturisasi folder — lihat
// docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// Rekomendasi Alokasi Aset (aset.js: AlokasiAset.renderOne(), target #aaResult,
// halaman Pajak & Zakat / tab Zakat). MODUL BARU — tidak mengubah satu baris
// pun logic AlokasiAset/Aset yang sudah ada; file ini HANYA menambah satu
// section baru yang di-append SETELAH box.innerHTML AlokasiAset ditulis (pola
// persis sama dgn self-reward-ai-widget.js -> SelfRewardAI.mountInto()).
//
// TUJUAN: baca kondisi investasi/aset senyata mungkin (bukan cuma ilustrasi
// alokasi preset) dari beberapa sumber, semua lewat guard
// `typeof X!=='undefined'` supaya aman dites/berdiri sendiri:
//   - D.assets (Buku Aset, aset.js)   -> diversifikasi aset "investasi"
//     (yg ditandai zakatable: Emas/Deposito/Saham/Reksadana/Kripto/tanah dst)
//   - D.assetAllocation (preset risiko terpilih user, aset.js)
//   - D.targets isDanaDarurat          -> cek dana darurat sblm alokasi lain
//   - Investment.portfolioSummary()/getHoldings() (investasi.js, kalau modul
//     portofolio itu dipakai) -> ROI & alokasi per jenis instrumen

function _iaFmtRp(n) {
  return typeof fmt === 'function' ? fmt(n) : 'Rp ' + Math.round(n || 0).toLocaleString('id-ID');
}
function _iaEsc(s) {
  return typeof escapeHtml === 'function' ? escapeHtml(String(s)) : String(s);
}

const InvestAI = {

  // Aset yang ditandai "Hitung ke Zakat Maal" = aset produktif/investasi
  // (definisi sama dgn yang dipakai FI Settings "Cakupan Aset untuk Target
  // FI" di modules-calc.js, supaya konsisten satu app).
  // S261 (Investment Ownership Sync): TAMBAH filter isAssetOwnershipSelf
  // (guard typeof, pola sama AssetPortfolioAPI.portfolioComposition()) —
  // SEBELUM sesi ini, rekomendasi diversifikasi/vs-preset di bawah bisa
  // ikut menghitung aset ber-ownership INVESTOR/CUSTOMER/THIRD_PARTY/
  // FAMILY, beda dari Aset.totalValue()/investmentPerformance() yang
  // sudah SELF-only. 0 rumus baru — cuma nambah 1 filter di atas filter
  // zakatable yang sudah ada.
  _investmentAssets() {
    if (typeof D === 'undefined' || !Array.isArray(D.assets)) return [];
    const selfOnly = typeof isAssetOwnershipSelf === 'function' ? isAssetOwnershipSelf : () => true;
    return D.assets.filter(selfOnly).filter((a) => a.zakatable);
  },

  // 1) Dana darurat harus lebih dulu beres sebelum alokasi ke instrumen lain.
  _checkDanaDarurat() {
    if (typeof D === 'undefined') return [];
    const dd = (D.targets || []).find((t) => t.isDanaDarurat);
    if (!dd) return []; // sudah ada banner khusus dari AlokasiAset sendiri
    const saved = dd.accountId && typeof recalcAccBalance === 'function' ? recalcAccBalance(dd.accountId) : dd.saved;
    const pct = dd.amount > 0 ? Math.round((saved / dd.amount) * 100) : 0;
    if (pct < 100) {
      return [{
        icon: '🚨',
        text: `Dana darurat baru ${pct}% dari target. Sebelum menambah alokasi ke instrumen berisiko, prioritaskan dulu sampai 100%.`,
        priority: 1,
      }];
    }
    return [];
  },

  // 2) Diversifikasi Buku Aset — flag kalau >60% nilai aset investasi
  // menumpuk di satu jenis (mis. semua di Emas atau semua di satu Saham).
  _checkDiversifikasi() {
    const list = InvestAI._investmentAssets();
    if (list.length < 2) return [];
    const total = list.reduce((s, a) => s + (a.nilai || 0), 0);
    if (total <= 0) return [];
    const byJenis = {};
    list.forEach((a) => {
      byJenis[a.jenis] = (byJenis[a.jenis] || 0) + (a.nilai || 0);
    });
    const dominant = Object.entries(byJenis)
      .map(([jenis, val]) => ({ jenis, pct: (val / total) * 100 }))
      .sort((a, b) => b.pct - a.pct)[0];
    if (dominant && dominant.pct >= 60) {
      return [{
        icon: '⚖️',
        text: `${Math.round(dominant.pct)}% aset investasi kamu ada di "${_iaEsc(dominant.jenis)}". Pertimbangkan diversifikasi ke jenis lain supaya risikonya lebih menyebar.`,
        priority: 2,
      }];
    }
    return [];
  },

  // 3) Bandingkan komposisi Buku Aset aktual vs preset risiko yang dipilih
  // user di AlokasiAset (kalau ada) — cari kesenjangan terbesar.
  _checkVsPreset(risk) {
    if (!risk || typeof ALOKASI_PRESETS === 'undefined' || !ALOKASI_PRESETS[risk]) return [];
    const list = InvestAI._investmentAssets();
    const total = list.reduce((s, a) => s + (a.nilai || 0), 0);
    if (total <= 0) return [];
    const jenisMap = {
      'Emas/Logam Mulia': 'Emas',
      'Deposito/Investasi': 'RDPU / Deposito',
      'Saham': 'Reksadana Saham / Saham',
      'Reksadana': 'Reksadana Saham / Saham',
      'Kripto': 'Kripto / Alternatif',
    };
    const actualPct = {};
    list.forEach((a) => {
      const label = jenisMap[a.jenis];
      if (!label) return;
      actualPct[label] = (actualPct[label] || 0) + ((a.nilai || 0) / total) * 100;
    });
    const preset = ALOKASI_PRESETS[risk];
    let biggestGap = null;
    preset.items.forEach((it) => {
      if (/dana darurat/i.test(it.name)) return; // sudah dicek terpisah
      const actual = actualPct[it.name] || 0;
      const gap = it.pct - actual;
      if (gap > 15 && (!biggestGap || gap > biggestGap.gap)) {
        biggestGap = { name: it.name, gap, target: it.pct, actual: Math.round(actual) };
      }
    });
    if (biggestGap) {
      return [{
        icon: '🧭',
        text: `Profil "${risk}" menyarankan ~${biggestGap.target}% di ${_iaEsc(biggestGap.name)}, tapi Buku Aset kamu baru ${biggestGap.actual}% di sana. Bisa jadi bahan pertimbangan alokasi berikutnya.`,
        priority: 3,
      }];
    }
    return [];
  },

  // 4) Kalau modul portofolio (Investment, investasi.js) dipakai — ROI &
  // konsentrasi holding, terpisah dari Buku Aset di atas.
  // S261 (Investment Ownership Sync): gate keberadaan holding sekarang
  // pakai summary.holdingsCount (SUDAH difilter isHoldingOwnershipSelf
  // sejak S193 di Investment.portfolioSummary()), BUKAN lagi
  // Investment.getHoldings().length mentah — supaya widget ini tidak
  // "kebuka" gate-nya hanya krn ada holding ber-ownership
  // INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY (summary/roiPct yang dipakai di
  // bawah sudah SELF-only, tapi gate-nya sendiri sebelumnya belum
  // konsisten). 0 rumus baru.
  _checkPortofolio() {
    if (typeof Investment === 'undefined') return [];
    const summary = Investment.portfolioSummary ? Investment.portfolioSummary() : null;
    if (!summary || !summary.holdingsCount) return [];
    const out = [];
    if (summary && summary.roiPct < 0) {
      out.push({
        icon: '📉',
        text: `Portofolio (holding tercatat) sedang minus ${summary.roiPct.toFixed(1)}% (unrealized) — belum tentu masalah kalau horisonnya masih panjang, tapi jangan buru-buru nambah di instrumen yang sama.`,
        priority: 2,
      });
    }
    return out;
  },

  // ---------- API utama ----------
  generateRecommendations() {
    if (typeof D === 'undefined') return [];
    const risk = D.assetAllocation && D.assetAllocation.risk;
    const all = [
      ...InvestAI._checkDanaDarurat(),
      ...InvestAI._checkDiversifikasi(),
      ...InvestAI._checkVsPreset(risk),
      ...InvestAI._checkPortofolio(),
    ];
    return all.sort((a, b) => a.priority - b.priority).slice(0, 5);
  },

  buildWidgetHtml(recommendations) {
    const list = recommendations && recommendations.length ? recommendations : null;
    const itemsHtml = list
      ? list.map((r) => `<div class="fg" style="display:flex;gap:8px;align-items:flex-start;margin-bottom:8px">
          <span>${r.icon}</span><span style="font-size:12px;line-height:1.5">${_iaEsc(r.text)}</span>
        </div>`).join('')
      : `<div class="fg" style="font-size:12px;color:var(--text2)">Belum cukup data (isi Buku Aset & pilih profil risiko dulu) untuk rekomendasi otomatis.</div>`;
    return `
      <div class="u-fs11 u-t2 u-mt10 u-mb4" style="font-weight:700;text-transform:uppercase;letter-spacing:.5px">🤖 Rekomendasi AI</div>
      <div id="investAiList">${itemsHtml}</div>
    `;
  },

  // mountInto(box) — SATU-SATUNYA fungsi yang sentuh DOM. Dipanggil dari
  // aset.js (AlokasiAset.renderOne) SETELAH box.innerHTML preset alokasi
  // ditulis; widget di-APPEND (bukan menimpa) supaya ilustrasi alokasi yang
  // sudah ada tetap utuh.
  mountInto(box) {
    if (!box || typeof document === 'undefined') return;
    const old = box.querySelector ? box.querySelector('#investAiWidget') : document.getElementById('investAiWidget');
    if (old && old.parentNode) old.parentNode.removeChild(old);
    const wrap = document.createElement('div');
    wrap.id = 'investAiWidget';
    wrap.innerHTML = InvestAI.buildWidgetHtml(InvestAI.generateRecommendations());
    box.appendChild(wrap);
  },
};

if (typeof window !== 'undefined') {
  window.InvestAI = InvestAI;
}

// penyusutan-ai-widget.js — Widget "🤖 Rekomendasi AI" utk kartu 📉 Penyusutan
// Dipindah ke modules/asset/penyusutan-ai-widget.js (Sesi 9 restrukturisasi folder — lihat
// docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// Aset (aset.js: Penyusutan.renderList(), target #assetPenyusutanAI, halaman
// Aset). MODUL BARU — tidak mengubah satu baris pun logic Penyusutan/Aset yang
// sudah ada; file ini HANYA render ke satu container baru yang dipanggil
// SETELAH box #assetPenyusutanList ditulis (pola sama persis dgn
// invest-ai-widget.js -> InvestAI.mountInto(), dipanggil dari
// AlokasiAset.renderOne()).
//
// TUJUAN: baca kondisi D.assets (Buku Aset, aset.js) + setting a.penyusutan
// tiap aset, semua lewat guard `typeof X!=='undefined'` spy aman
// dites/berdiri sendiri, lalu kasih catatan praktis (BUKAN saran akuntansi/
// pajak berlisensi):
//   - Aset yang jenisnya biasanya MENURUN nilainya (Kendaraan/Rumah-Bangunan)
//     tapi penyusutannya belum diaktifkan sama sekali.
//   - Aset Tanah yang malah diaktifkan penyusutannya (tanah lazimnya TIDAK
//     disusutkan krn nilainya cenderung naik/stabil, beda dgn bangunan di
//     atasnya).
//   - Aset yang penyusutannya aktif tapi datanya belum lengkap (Harga
//     Perolehan kosong) — sudah ada warning per-baris, di sini direkap jadi
//     satu catatan ringkas kalau lebih dari satu.
//   - Aset (metode Garis Lurus) yang sudah mencapai akhir umur manfaat.
//   - Aset yang nilai bukunya sudah tersisa sangat kecil (<=20%) dari Harga
//     Perolehan tapi belum habis umur manfaat — sinyal utk cek kondisi fisik.

function _paFmtRp(n) {
  return typeof fmtFull === 'function' ? fmtFull(n) : 'Rp ' + Math.round(n || 0).toLocaleString('id-ID');
}
function _paEsc(s) {
  return typeof escapeHtml === 'function' ? escapeHtml(String(s)) : String(s);
}

// Jenis aset yang LAZIMNYA menurun nilainya (kandidat kuat utk penyusutan).
const PENYUSUTAN_AI_JENIS_MENURUN = ['Kendaraan', 'Rumah/Bangunan'];
// Jenis aset yang LAZIMNYA tidak disusutkan (nilai cenderung naik/stabil).
const PENYUSUTAN_AI_JENIS_TIDAK_SUSUT = ['Tanah', 'Emas/Logam Mulia', 'Saham', 'Reksadana', 'Kripto', 'Deposito/Investasi'];

const PenyusutanAI = {

  _assets() {
    if (typeof D === 'undefined' || !Array.isArray(D.assets)) return [];
    return D.assets;
  },

  // 1) Kandidat kuat (Kendaraan/Rumah-Bangunan) yang belum aktifkan penyusutan.
  _checkBelumAktif() {
    const list = PenyusutanAI._assets().filter((a) => PENYUSUTAN_AI_JENIS_MENURUN.includes(a.jenis) && !(a.penyusutan && a.penyusutan.aktif));
    if (!list.length) return [];
    const contoh = list.slice(0, 3).map((a) => _paEsc(a.name)).join(', ');
    const sisa = list.length > 3 ? ` (+${list.length - 3} lagi)` : '';
    return [{
      icon: '📉',
      text: `${list.length} aset (${contoh}${sisa}) biasanya nilainya menurun dari waktu ke waktu, tapi penyusutannya belum diaktifkan. Aktifkan supaya Nilai Buku & estimasi Kekayaan Bersih lebih realistis.`,
      priority: 2,
    }];
  },

  // 2) Tanah yang malah diaktifkan penyusutannya (lazimnya tidak disusutkan).
  _checkTanahDisusutkan() {
    const list = PenyusutanAI._assets().filter((a) => PENYUSUTAN_AI_JENIS_TIDAK_SUSUT.includes(a.jenis) && a.penyusutan && a.penyusutan.aktif);
    if (!list.length) return [];
    const contoh = list.slice(0, 3).map((a) => _paEsc(a.name)).join(', ');
    const sisa = list.length > 3 ? ` (+${list.length - 3} lagi)` : '';
    return [{
      icon: '🧭',
      text: `Penyusutan aktif di ${contoh}${sisa} — jenis aset ini lazimnya nilainya cenderung naik/stabil (bukan menurun), jadi penyusutan mungkin kurang cocok. Pertimbangkan matikan & pantau nilainya lewat kartu 💹 Performa Investasi saja.`,
      priority: 3,
    }];
  },

  // 3) Penyusutan aktif tapi Harga Perolehan belum diisi (tidak bisa dihitung).
  _checkDataBelumLengkap() {
    if (typeof Penyusutan === 'undefined') return [];
    const list = PenyusutanAI._assets().filter((a) => a.penyusutan && a.penyusutan.aktif && a.penyusutan.metode !== 'manual' && Penyusutan.hargaPerolehan(a) == null);
    if (!list.length) return [];
    const contoh = list.slice(0, 3).map((a) => _paEsc(a.name)).join(', ');
    const sisa = list.length > 3 ? ` (+${list.length - 3} lagi)` : '';
    return [{
      icon: '⚠️',
      text: `${list.length} aset (${contoh}${sisa}) sudah aktifkan penyusutan tapi Modal Investasi / Harga Beli × Jumlah Unit-nya belum diisi, jadi belum bisa dihitung. Lengkapi dulu lewat Edit Aset.`,
      priority: 1,
    }];
  },

  // 4) Aset (Garis Lurus) yang sudah mencapai akhir umur manfaat.
  _checkHabisManfaat() {
    if (typeof Penyusutan === 'undefined') return [];
    const list = PenyusutanAI._assets().filter((a) => {
      if (!(a.penyusutan && a.penyusutan.aktif)) return false;
      const hasil = Penyusutan.hitung(a);
      return !!(hasil && hasil.habisManfaat);
    });
    if (!list.length) return [];
    const contoh = list.slice(0, 3).map((a) => _paEsc(a.name)).join(', ');
    const sisa = list.length > 3 ? ` (+${list.length - 3} lagi)` : '';
    return [{
      icon: '✅',
      text: `${list.length} aset (${contoh}${sisa}) sudah mencapai akhir umur manfaat estimasinya. Kalau masih dipakai, tidak masalah; kalau sudah waktunya ganti, ini bisa jadi pengingat evaluasi.`,
      priority: 4,
    }];
  },

  // 5) Nilai buku tersisa <=20% dari Harga Perolehan tapi belum habis manfaat.
  _checkNilaiBukuKecil() {
    if (typeof Penyusutan === 'undefined') return [];
    const hits = [];
    PenyusutanAI._assets().forEach((a) => {
      if (!(a.penyusutan && a.penyusutan.aktif)) return;
      const hasil = Penyusutan.hitung(a);
      if (!hasil || hasil.habisManfaat || hasil.hargaPerolehan == null || hasil.hargaPerolehan <= 0) return;
      const pct = hasil.nilaiBuku / hasil.hargaPerolehan;
      if (pct <= 0.2) hits.push({ name: a.name, pct, nilaiBuku: hasil.nilaiBuku });
    });
    if (!hits.length) return [];
    hits.sort((a, b) => a.pct - b.pct);
    const worst = hits[0];
    const sisa = hits.length > 1 ? ` (+${hits.length - 1} aset lain dgn kondisi serupa)` : '';
    return [{
      icon: '🔧',
      text: `Nilai buku ${_paEsc(worst.name)} tinggal ${Math.round(worst.pct * 100)}% (${_paFmtRp(worst.nilaiBuku)}) dari Harga Perolehan${sisa}. Kalau ini kendaraan/peralatan yang masih dipakai, cek kondisi fisiknya — kadang saat ini justru momen yang pas buat rencanakan penggantian.`,
      priority: 4,
    }];
  },

  // ---------- API utama ----------
  generateRecommendations() {
    if (typeof D === 'undefined') return [];
    const all = [
      ...PenyusutanAI._checkDataBelumLengkap(),
      ...PenyusutanAI._checkBelumAktif(),
      ...PenyusutanAI._checkTanahDisusutkan(),
      ...PenyusutanAI._checkHabisManfaat(),
      ...PenyusutanAI._checkNilaiBukuKecil(),
    ];
    return all.sort((a, b) => a.priority - b.priority).slice(0, 5);
  },

  buildWidgetHtml(recommendations) {
    const list = recommendations && recommendations.length ? recommendations : null;
    const itemsHtml = list
      ? list.map((r) => `<div class="fg" style="display:flex;gap:8px;align-items:flex-start;margin-bottom:8px">
          <span>${r.icon}</span><span style="font-size:12px;line-height:1.5">${r.text}</span>
        </div>`).join('')
      : `<div class="fg" style="font-size:12px;color:var(--text2)">Belum ada catatan otomatis — aktifkan penyusutan di aset yang relevan (kendaraan/bangunan) supaya rekomendasi mulai muncul di sini.</div>`;
    return `
      <div class="u-fs11 u-t2 u-mt10 u-mb4" style="font-weight:700;text-transform:uppercase;letter-spacing:.5px">🤖 Rekomendasi AI</div>
      <div id="penyusutanAiList">${itemsHtml}</div>
    `;
  },

  // mountInto(el) — SATU-SATUNYA fungsi yang sentuh DOM. Dipanggil dari
  // aset.js (Penyusutan.renderList()) SETELAH #assetPenyusutanList ditulis.
  // Container-nya sendiri (#assetPenyusutanAI) TERPISAH dari box per-aset,
  // jadi di sini boleh langsung set innerHTML (bukan append spt InvestAI,
  // krn tidak ada konten lain yg perlu dipertahankan di container ini).
  mountInto(el) {
    if (!el || typeof document === 'undefined') return;
    el.innerHTML = PenyusutanAI.buildWidgetHtml(PenyusutanAI.generateRecommendations());
  },
};

if (typeof window !== 'undefined') {
  window.PenyusutanAI = PenyusutanAI;
}

// aset-emas-impor.js — FITUR BARU: GoldImport (impor massal nota emas via paste teks ATAU
// Dipindah ke modules/asset/aset-emas-impor.js (Sesi 9 restrukturisasi folder — lihat
// docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// upload file .xlsx rekap nota) & GoldZakat (rekap emas utk zakat maal + analisa harga/gram
// & untung-rugi).
// CARA PASANG (lihat juga INTEGRASI-EMAS.md):
//   1. Salin file ini ke folder proyek (sejajar dgn aset.js).
//   2. Di build.js, tambahkan 'aset-emas-impor.js' ke GROUP_A, TEPAT SETELAH 'aset.js'
//      (module ini pakai Aset.ICON, D.assets, parsePzNum, uid(), save(), toast(), dst yg
//      sudah didefinisikan di aset.js / features-helpers-global-security.js. Utk fitur
//      import .xlsx, pakai ensureXLSX() global yg sama dipakai Aset.exportXLSX/importXLSX
//      di aset.js & ShopExport/ImportShopExcel di cobek.js — TIDAK nambah pustaka baru).
//   3. Tambahkan 2 modal baru ke modals.js — markup ada di file goldModals.html. Tambahkan
//      juga tombol upload xlsx & input file tersembunyi di dalam goldImportModal (lihat
//      contoh markup di komentar atas GoldImport.openXLSXPicker di bawah).
//   4. Tambahkan tombol pembuka di halaman Buku Aset (lihat INTEGRASI-EMAS.md), mis:
//      <button class="btn btn-ghost btn-full btn-sm u-mb10" data-action="GoldImport.open">📋 Impor Nota Emas (Massal)</button>
//      <button class="btn btn-ghost btn-full btn-sm u-mb10" data-action="GoldZakat.open">🕌 Analisa Zakat Emas</button>
//   5. Jalankan `node build.js` seperti biasa supaya masuk ke app-bundle-a.min.js.
//
// FORMAT XLSX YANG DITERIMA (kolom dicari via NAMA HEADER, urutan kolom bebas, header lain
// selain daftar di bawah diabaikan — jadi file "rekap nota emas" hasil catatan manual bisa
// langsung dipakai tanpa harus disamakan persis dgn format Aset.exportXLSX):
//   Tanggal                              — tanggal nota (boleh cell Date Excel atau teks)
//   Toko (Staf)                          — nama toko/staf yg layani (opsional)
//   Atas Nama                            — nama pemilik/pembeli di nota (opsional)
//   Jenis Perhiasan & Spesifikasi Detail — dipakai deteksi jenis (Cincin/Kalung/dst)
//   Kadar (‰)                            — kadar per mil, mis. 750
//   Berat (gram)                         — berat fisik dari nota
//   Harga/gram (Rp)                      — opsional, dihitung dari Total÷Berat kalau kosong
//   Total Harga Riil (Rp)                — opsional, dihitung dari Berat×Harga/gram kalau kosong
// Baris tanpa Berat DAN tanpa Total (dua-duanya kosong/nol) dilewati (dianggap bukan nota,
// mis. baris "TOTAL" rekap atau baris kosong).
//
// DATA MODEL: setiap item emas hasil impor disimpan sbg entri biasa di D.assets dengan
// jenis:'Emas/Logam Mulia', zakatable:true (default), plus field tambahan khusus emas:
//   goldKadar        — kadar per mil (mis. 750, 700, 916, 999)
//   goldBeratGram     — berat fisik dari nota (gram, apa adanya di nota)
//   goldHargaPerGram  — harga per gram SESUAI KADAR itu (bukan disetarakan 24K)
//   goldJenis         — 'Cincin' | 'Kalung' | 'Gelang' | 'Anting' | 'Liontin' | 'Lainnya'
//   goldToko          — nama toko/atas nama di nota (opsional, buat referensi)
// Field goldKadar/goldBeratGram dipakai GoldZakat utk hitung total gram setara 24K.
// Aset lama (yg sudah ada sebelum fitur ini) yg jenisnya 'Emas/Logam Mulia' tapi TIDAK
// punya goldKadar/goldBeratGram tetap ikut dihitung ke total NILAI (nilai Rp), tapi
// tidak ikut dihitung ke total GRAM (krn kita tidak tahu beratnya) — GoldZakat kasih
// peringatan soal ini biar user sadar & bisa lengkapi manual kalau mau akurat.

const GoldImport={
parsed:[],
open(){
this.parsed=[];
const ta=document.getElementById('goldImportText');
if(ta)ta.value='';
const box=document.getElementById('goldImportPreview');
if(box)box.innerHTML='';
const btn=document.getElementById('goldImportCommitBtn');
if(btn)btn.disabled=true;
openModal('goldImportModal');
},
// --- deteksi jenis perhiasan dari teks bebas ---
_detectJenis(text){
const t=text.toLowerCase();
// BUGFIX: pakai \b (word boundary) supaya nama kota spt "Magelang" tidak
// ke-deteksi salah jadi jenis "Gelang" (krn "Magelang" mengandung substring
// "gelang" tapi bukan kata "gelang" yg berdiri sendiri). Ketemu saat test
// import 6 nota asli dari rekap-nota-emas.xlsx (nota dari toko "Mustika Gold
// Magelang" jenisnya "Anting" tapi ke-deteksi "Gelang").
if(/\bcincin\b/.test(t))return 'Cincin';
if(/\bkalung\b|\brantai\b|\bliontin\b|\bsusup\b|\bsusun\b/.test(t))return 'Kalung';
if(/\bgelang\b/.test(t))return 'Gelang';
if(/\banting\b/.test(t))return 'Anting';
return 'Lainnya';
},
// --- parser 1 blok nota (multi-baris bebas, ditempel apa adanya dari WA/catatan) ---
// Pola yg dicari, masing2 opsional & bisa muncul di baris mana saja dalam 1 blok:
//   Tanggal   : "18-7-2020" / "18/07/2020" / "18 Juli 2020"
//   Nama/Toko : baris "Nama : Alina" atau baris pertama non-angka jika ada
//   Kadar     : "750", "700", "916", "999" (angka 3 digit berdiri sendiri, atau "@755"→harga bukan kadar)
//   Berat     : "B: 4.130 g" / "berat 4,13 gr" / "4.130g"
//   Harga/gram: "@755" / "harga 755000/gr"
//   Total     : "JUMLAH 3.118.000" / "Rp 3.118.000" (angka terbesar di blok biasanya total)
_parseBlock(text){
const raw=text;
const lower=raw.toLowerCase();
const jenis=this._detectJenis(raw);
// tanggal
let tanggal='';
const dm=raw.match(/(\d{1,2})[\s./-](\d{1,2}|[a-zA-Z]+)[\s./-](\d{4})/);
if(dm){
const bulanMap={jan:1,januari:1,feb:2,februari:2,mar:3,maret:3,apr:4,april:4,mei:5,jun:6,juni:6,jul:7,juli:7,agu:8,agustus:8,sep:9,september:9,okt:10,oktober:10,nov:11,november:11,des:12,desember:12};
let bln=dm[2];
if(isNaN(parseInt(bln,10))){
const key=bln.toLowerCase().slice(0,3);
bln=bulanMap[key]||bulanMap[bln.toLowerCase()]||1;
} else bln=parseInt(bln,10);
const dd=String(parseInt(dm[1],10)).padStart(2,'0');
const mm=String(bln).padStart(2,'0');
tanggal=`${dm[3]}-${mm}-${dd}`;
}
// kadar (750/700/833/875/916/999) — cari token 3 digit yg BUKAN didahului '@' (itu harga)
let kadar=750;
const kadarMatch=raw.match(/(?<!@)\b(700|750|833|840|875|916|920|999)\b/);
if(kadarMatch)kadar=parseInt(kadarMatch[1],10);
// berat gram — pola "B: 4.130 g" / "berat 4,13" / angka diikuti g/gr/gram
let berat=0;
const beratMatch=raw.match(/b\s*[:=]?\s*([\d.,]+)\s*g/i)||raw.match(/berat\s*[:=]?\s*([\d.,]+)/i)||raw.match(/([\d.,]+)\s*(?:gr|gram)\b/i);
if(beratMatch)berat=parseDecStr(beratMatch[1])||0;
// harga per gram — pola "@755" artinya 755rb/gram (konvensi toko emas)
let hargaPerGram=0;
const hpgMatch=raw.match(/@\s*(\d{2,4})/);
if(hpgMatch)hargaPerGram=parseInt(hpgMatch[1],10)*1000;
// total harga — cari "jumlah"/"total" diikuti angka, kalau tidak ada ambil angka terbesar
let total=0;
const jumlahMatch=raw.match(/(?:jumlah|total)\s*[:.]?\s*(?:rp\.?)?\s*([\d.,]+)/i);
if(jumlahMatch)total=this._toNumber(jumlahMatch[1]);
if(!total){
const allNums=(raw.match(/\d[\d.,]{4,}/g)||[]).map(s=>this._toNumber(s)).filter(n=>n>1000);
if(allNums.length)total=Math.max(...allNums);
}
if(total&&berat&&!hargaPerGram)hargaPerGram=Math.round(total/berat);
if(!total&&berat&&hargaPerGram)total=Math.round(berat*hargaPerGram);
// nama/toko — baris "Nama :" kalau ada
let nama='';
const namaMatch=raw.match(/nama\s*:?\s*([a-zA-Z. ]{2,30})/i);
if(namaMatch)nama=namaMatch[1].trim();
return {tanggal,kadar,berat,hargaPerGram,total,jenis,nama,rawText:raw.trim()};
},
_toNumber(s){
// "3.118.000" -> 3118000 ; "3,118,000" -> 3118000 ; "3118000" -> 3118000
const cleaned=String(s).replace(/[^\d.,]/g,'');
const noThousand=cleaned.replace(/[.,](?=\d{3}(?:\D|$))/g,'');
return parseInt(noThousand.replace(/[.,]/g,''),10)||0;
},
preview(){
const ta=document.getElementById('goldImportText');
const text=ta?ta.value:'';
if(!text.trim()){toast('⚠️ Tempel dulu isi nota emas di kotak teks');return;}
// pisah per blok pakai baris kosong ganda, ATAU baris yg mengandung "Toko Mas"/"Nota"/tanggal baru
const blocks=text.split(/\n\s*\n+/).map(b=>b.trim()).filter(Boolean);
const items=blocks.map(b=>this._parseBlock(b)).filter(it=>it.berat>0||it.total>0);
this._setParsed(items,'Tidak ada nota yg kebaca. Pisahkan tiap nota dgn 1 baris kosong. Pastikan tiap blok ada info berat (mis. "B: 4.130 g") dan harga/total (mis. "JUMLAH 3.118.000" atau "@755").');
},
// --- render ulang preview + enable/disable tombol commit, dipakai bareng oleh flow paste-teks
// (preview) & flow upload-xlsx (importXLSXFile) supaya UI & tombol Impor sama persis ---
_setParsed(items,emptyMsg){
this.parsed=items;
const box=document.getElementById('goldImportPreview');
const btn=document.getElementById('goldImportCommitBtn');
if(!box)return;
if(!items.length){
box.innerHTML='<div class="u-fs12 u-t2">'+emptyMsg+'</div>';
if(btn)btn.disabled=true;
return;
}
box.innerHTML=items.map((it,i)=>`<div style="padding:8px 0;border-bottom:1px solid var(--border);font-size:12px">
<div style="font-weight:700">${it.jenis}${it.nama?' — '+escapeHtml(it.nama):''}${it.tanggal?' · '+it.tanggal:''}</div>
<div class="u-t2">Kadar ${it.kadar} · Berat ${it.berat.toFixed(3)}g · @${fmtFull(it.hargaPerGram)} · Total ${fmtFull(it.total)}</div>
</div>`).join('');
if(btn)btn.disabled=false;
},
// --- lazy-load SheetJS, pola identik Aset._ensureXLSXLib di aset.js (satu pustaka, dua tempat pakai) ---
async _ensureXLSXLib(){
if(typeof XLSX!=='undefined')return true;
try{ await ensureXLSX(); }catch(e){ toast('⚠️ Gagal memuat pustaka Excel, cek koneksi internet'); return false; }
if(typeof XLSX==='undefined'){ toast('⚠️ Pustaka Excel tidak tersedia'); return false; }
return true;
},
// --- buka file picker tersembunyi. Markup input yg perlu ditambahkan di goldImportModal:
//   <input type="file" id="goldImportXLSXFile" accept=".xlsx,.xls" class="u-dnone" onchange="GoldImport.importXLSXFile(event)">
//   <button type="button" class="btn btn-ghost btn-full btn-sm u-mb10" data-action="GoldImport.openXLSXPicker">📥 Upload Rekap Nota (.xlsx)</button>
openXLSXPicker(){
const inp=document.getElementById('goldImportXLSXFile');
if(inp)inp.click();
},
// --- baca 1 baris rekap xlsx (object hasil XLSX.utils.sheet_to_json) jadi bentuk yg sama
// dgn output _parseBlock() diatas, supaya bisa lewat preview/commit yg sama persis ---
_parseXLSXRow(r){
const jenisTeks=String(r['Jenis Perhiasan & Spesifikasi Detail']||r['Jenis Perhiasan']||r['Jenis']||'');
const jenis=this._detectJenis(jenisTeks);
// tanggal: SheetJS (cellDates:true) bisa kasih objek Date asli, atau tetap string kalau
// cell-nya format teks -- tangani dua-duanya.
let tanggal='';
const rawTgl=r['Tanggal'];
if(rawTgl instanceof Date&&!isNaN(rawTgl)){
tanggal=rawTgl.getFullYear()+'-'+String(rawTgl.getMonth()+1).padStart(2,'0')+'-'+String(rawTgl.getDate()).padStart(2,'0');
}else if(rawTgl){
const dm=String(rawTgl).match(/(\d{4})-(\d{1,2})-(\d{1,2})/)||String(rawTgl).match(/(\d{1,2})[\s./-](\d{1,2})[\s./-](\d{4})/);
if(dm){
if(dm[1].length===4)tanggal=dm[1]+'-'+dm[2].padStart(2,'0')+'-'+dm[3].padStart(2,'0');
else tanggal=dm[3]+'-'+dm[2].padStart(2,'0')+'-'+dm[1].padStart(2,'0');
}
}
const kadar=parseInt(r['Kadar (‰)']||r['Kadar']||0,10)||750;
const berat=parseDecStr(String(r['Berat (gram)']||r['Berat']||'').trim())||Number(r['Berat (gram)'])||0;
let hargaPerGram=Number(r['Harga/gram (Rp)']||r['Harga per Gram']||0)||0;
let total=Number(r['Total Harga Riil (Rp)']||r['Total']||0)||0;
if(total&&berat&&!hargaPerGram)hargaPerGram=Math.round(total/berat);
if(!total&&berat&&hargaPerGram)total=Math.round(berat*hargaPerGram);
// nama/referensi nota: gabung Toko (Staf) + Atas Nama kalau dua-duanya ada, biar tetap
// jelas rujukannya di Buku Aset (field goldToko cuma 1 kolom teks)
const toko=String(r['Toko (Staf)']||r['Toko']||'').trim();
const atasNama=String(r['Atas Nama']||r['Nama']||'').trim();
let nama=toko;
if(atasNama)nama=nama?(nama+' · a.n. '+atasNama):atasNama;
return {tanggal,kadar,berat,hargaPerGram,total,jenis,nama,rawText:JSON.stringify(r)};
},
// --- cari baris header tabel secara otomatis lalu bangun array objek {header:nilai}
// dari baris2 sesudahnya. BUGFIX: dulu pakai XLSX.utils.sheet_to_json(ws,{defval:''})
// polos yg SELALU asumsikan baris PERTAMA sheet = header -- gagal total kalau file
// rekap punya judul/subjudul/baris kosong di atas tabel (pola umum: baris 1 judul,
// baris 2 keterangan sumber, baris 3 kosong, baris 4 baru header asli "No/Toko
// (Staf)/Tanggal/dst"). Ketemu nyata dari laporan user pakai file rekap-nota-emas-v2.xlsx
// yg persis berformat begini -- semua baris kebaca tapi ke-mapping ke key yg salah
// (key jadi teks judul), jadi importXLSXFile() selalu bilang "tidak ada nota kebaca".
_sheetToRows(ws){
const aoa=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});
const HEADER_MARKERS=['Tanggal','Toko (Staf)','Atas Nama','Jenis Perhiasan & Spesifikasi Detail','Kadar (‰)','Berat (gram)','Harga/gram (Rp)','Total Harga Riil (Rp)'];
let headerIdx=-1;
for(let i=0;i<Math.min(aoa.length,25);i++){
const cells=(aoa[i]||[]).map(c=>String(c==null?'':c).trim());
const hits=HEADER_MARKERS.filter(h=>cells.includes(h)).length;
if(hits>=2){headerIdx=i;break;}
}
if(headerIdx===-1)headerIdx=0; // fallback: pola lama (header = baris pertama)
const headers=(aoa[headerIdx]||[]).map(h=>String(h==null?'':h).trim());
const out=[];
for(let i=headerIdx+1;i<aoa.length;i++){
const row=aoa[i]||[];
const allEmpty=row.every(c=>c===''||c==null);
if(allEmpty)continue; // baris kosong pemisah
const firstCell=String(row[0]==null?'':row[0]).trim().toUpperCase();
if(firstCell==='TOTAL'||firstCell==='JUMLAH')continue; // baris rekap total, bukan nota
const obj={};
headers.forEach((h,idx)=>{ if(h)obj[h]=row[idx]; });
out.push(obj);
}
return out;
},
async importXLSXFile(e){
const file=e.target.files[0];if(!file)return;
if(!await this._ensureXLSXLib()){e.target.value='';return;}
let rows;
try{
const buf=await file.arrayBuffer();
const wb=XLSX.read(buf,{type:'array',cellDates:true});
const ws=wb.Sheets[wb.SheetNames[0]];
rows=this._sheetToRows(ws);
}catch{
toast('❌ File tidak valid / rusak (bukan Excel)!');
e.target.value='';
return;
}
const items=rows.map(r=>this._parseXLSXRow(r)).filter(it=>it.berat>0||it.total>0);
this._setParsed(items,'Tidak ada nota valid ditemukan di file ini. Pastikan ada kolom "Berat (gram)" dan/atau "Total Harga Riil (Rp)" terisi di tiap baris nota (baris rekap "TOTAL" atau baris kosong otomatis dilewati).');
if(items.length)toast('✅ '+items.length+' baris nota kebaca dari file — cek pratinjau lalu tap Impor');
e.target.value='';
},
commit(){
if(!this.parsed.length){toast('⚠️ Belum ada yg dipratinjau');return;}
let count=0;
this.parsed.forEach(it=>{
D.assets.push({
id:uid(),
name:`${it.jenis} emas ${it.kadar}${it.nama?' — '+it.nama:''}`,
jenis:'Emas/Logam Mulia',
lokasi:it.nama?('Nota: '+it.nama):'',
nilai:it.total||Math.round((it.berat||0)*(it.hargaPerGram||0)),
tanggal:it.tanggal||todayStr(),
zakatable:true,
accountId:null,
modalInvestasi:it.total||null,
hargaBeli:it.hargaPerGram||null,
jumlahUnit:it.berat||null,
keuntungan:null,
keuntunganPct:null,
goldKadar:it.kadar,
goldBeratGram:it.berat,
goldHargaPerGram:it.hargaPerGram,
goldJenis:it.jenis,
goldToko:it.nama||''
});
count++;
});
save();
closeModal('goldImportModal');
Aset.renderList();renderKekayaanBersih();hitungZakatMaal();
toast(`✅ ${count} aset emas berhasil diimpor`);
}
};

const GoldZakat={
NISAB_GRAM_24K:85, // standar umum: 85 gram emas murni (24K)
ZAKAT_RATE:0.025,
// ambil semua aset emas yg punya data kadar+berat lengkap
_goldAssetsLengkap(){
return (D.assets||[]).filter(a=>a.jenis==='Emas/Logam Mulia'&&a.goldKadar&&a.goldBeratGram);
},
_goldAssetsTanpaData(){
return (D.assets||[]).filter(a=>a.jenis==='Emas/Logam Mulia'&&!(a.goldKadar&&a.goldBeratGram));
},
totalGram24kEquiv(){
return this._goldAssetsLengkap().reduce((s,a)=>s+(a.goldBeratGram*(a.goldKadar/1000)),0);
},
totalGramApaAdanya(){
return this._goldAssetsLengkap().reduce((s,a)=>s+a.goldBeratGram,0);
},
totalModal(){
const lengkap=this._goldAssetsLengkap().reduce((s,a)=>s+(a.modalInvestasi||a.nilai||0),0);
const tanpaData=this._goldAssetsTanpaData().reduce((s,a)=>s+(a.modalInvestasi||0),0);
return lengkap+tanpaData;
},
totalNilaiSekarang(hargaPerGram24k){
const dariLengkap=this.totalGram24kEquiv()*(hargaPerGram24k||0);
const dariTanpaData=this._goldAssetsTanpaData().reduce((s,a)=>s+(a.nilai||0),0);
return dariLengkap+dariTanpaData;
},
open(){
this.render();
openModal('goldZakatModal');
},
onHargaInput(){
D.goldZakatSettings=D.goldZakatSettings||{};
D.goldZakatSettings.hargaPerGram24k=parsePzNum(document.getElementById('gzHargaGram').value);
save();
this.render();
},
render(){
const box=document.getElementById('goldZakatBody');
if(!box)return;
const harga=(D.goldZakatSettings&&D.goldZakatSettings.hargaPerGram24k)||0;
const hargaInput=document.getElementById('gzHargaGram');
if(hargaInput&&!hargaInput.value)hargaInput.value=harga||'';
const gramEquiv=this.totalGram24kEquiv();
const gramApaAdanya=this.totalGramApaAdanya();
const modal=this.totalModal();
const nilaiSekarang=this.totalNilaiSekarang(harga);
const untung=nilaiSekarang-modal;
const untungPct=modal?(untung/modal*100):0;
const tanpaDataList=this._goldAssetsTanpaData();
const sudahNisab=gramEquiv>=this.NISAB_GRAM_24K;
const zakatWajib=sudahNisab?nilaiSekarang*this.ZAKAT_RATE:0;
const rekapPerJenis={};
this._goldAssetsLengkap().forEach(a=>{
const j=a.goldJenis||'Lainnya';
if(!rekapPerJenis[j])rekapPerJenis[j]={gram:0,gramEquiv:0,nilai:0,count:0};
rekapPerJenis[j].gram+=a.goldBeratGram;
rekapPerJenis[j].gramEquiv+=a.goldBeratGram*(a.goldKadar/1000);
rekapPerJenis[j].nilai+=(a.nilai||0);
rekapPerJenis[j].count++;
});
let html=`
<div class="fg"><label class="fl">Harga Emas Saat Ini per Gram (24K, Rp)</label>
<div class="amt-wrap">
<input type="text" class="fi fi-calc-only" id="gzHargaGram" placeholder="cth. 1.500.000" inputmode="decimal" value="${harga||''}" oninput="GoldZakat.onHargaInput()" onblur="evalAmtExpr('gzHargaGram');GoldZakat.onHargaInput()">
</div>
<div style="font-size:11px;color:var(--text2);margin-top:4px">Isi harga emas Antam/pasar hari ini per gram (24K) — dipakai utk estimasi nilai sekarang & cek Nisab. Cek harga terkini di Pegadaian/Antam/toko emas langganan.</div>
</div>
<div style="background:var(--surface3);border-radius:12px;padding:14px;margin-bottom:14px">
<div style="display:flex;justify-content:space-between;margin-bottom:6px"><span class="u-t2">Total berat (apa adanya)</span><b>${gramApaAdanya.toFixed(3)} gram</b></div>
<div style="display:flex;justify-content:space-between;margin-bottom:6px"><span class="u-t2">Total setara emas 24K</span><b>${gramEquiv.toFixed(3)} gram</b></div>
<div style="display:flex;justify-content:space-between;margin-bottom:6px"><span class="u-t2">Total modal/harga beli</span><b>${fmtFull(modal)}</b></div>
<div style="display:flex;justify-content:space-between;margin-bottom:6px"><span class="u-t2">Estimasi nilai sekarang</span><b>${fmtFull(nilaiSekarang)}</b></div>
<div style="display:flex;justify-content:space-between"><span class="u-t2">Untung/rugi vs modal</span><b class="${untung>=0?'green':'red'}">${untung>=0?'+':''}${fmtFull(untung)} (${untungPct>=0?'+':''}${untungPct.toFixed(1)}%)</b></div>
</div>
<div style="background:${sudahNisab?'var(--accent3-soft)':'var(--surface2)'};border-radius:12px;padding:14px;margin-bottom:14px">
<div class="u-fs12t2" style="margin-bottom:6px">Nisab zakat emas (standar umum: 85 gram emas 24K)</div>
<div style="font-family:'Space Grotesk',sans-serif;font-size:20px;font-weight:800;margin-bottom:4px">${sudahNisab?'✅ Sudah mencapai Nisab':'⏳ Belum mencapai Nisab'}</div>
<div class="u-fs12t2">${gramEquiv.toFixed(2)} gram / ${this.NISAB_GRAM_24K} gram nisab</div>
${sudahNisab?`<div style="margin-top:10px;padding-top:10px;border-top:1px dashed var(--border)">
<div style="display:flex;justify-content:space-between"><span class="u-fs12t2">Zakat Maal (2,5%, JIKA sudah haul 1 th Hijriah)</span><b style="color:var(--accent3)">${fmtFull(zakatWajib)}</b></div>
</div>`:''}
</div>`;
if(Object.keys(rekapPerJenis).length){
html+='<div class="card-title" style="margin-bottom:8px">Rincian per Jenis Perhiasan</div>';
Object.keys(rekapPerJenis).forEach(j=>{
const r=rekapPerJenis[j];
html+=`<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--border);font-size:12.5px">
<span>${j} (${r.count})</span><span>${r.gram.toFixed(3)}g · ${fmtFull(r.nilai)}</span>
</div>`;
});
}
if(tanpaDataList.length){
html+=`<div style="font-size:11px;color:var(--text2);line-height:1.5;margin-top:12px;padding:10px 12px;background:var(--accent2-soft);border-radius:10px">
⚠️ Ada ${tanpaDataList.length} aset emas TANPA data kadar/berat detail (dicatat manual sebelum fitur ini ada), jadi tidak ikut dihitung ke total gram di atas — hanya ikut ke nilai Rp. Edit aset itu satu-satu utk isi kadar & berat kalau mau perhitungan gram lebih akurat.</div>`;
}
html+=`<div style="font-size:11px;color:var(--text2);line-height:1.5;margin-top:12px">⚠️ Ini bukan fatwa resmi. Nisab (85gr) & tarif (2,5%) mengikuti pendapat yang umum dipakai — cek ke ustadz/lembaga amil zakat terpercaya utk kepastian hukum, terutama soal syarat haul (kepemilikan genap 1 tahun Hijriah) & apakah emas ini termasuk kategori wajib zakat (perhiasan pakai sehari-hari umumnya dikecualikan menurut sebagian ulama).</div>`;
box.innerHTML=html;
}
};

